from fastapi import FastAPI, File, Form, UploadFile
from fastapi.testclient import TestClient
import pytest

app = FastAPI()

@app.post("/upload")
async def upload(form_data: str = Form(...), file: bytes = File(...)):
    return {"form_data": form_data, "file_len": len(file)}

client = TestClient(app)

def test_upload_form_then_file():
    # This should work, but might fail with 422 if the bug is present
    response = client.post(
        "/upload",
        data={"form_data": "hello"},
        files={"file": b"world"}
    )
    print(f"Status: {response.status_code}")
    print(f"Body: {response.json()}")
    assert response.status_code == 200
    assert response.json() == {"form_data": "hello", "file_len": 5}

def test_upload_file_then_form():
    # This is the case that probably works
    @app.post("/upload_reversed")
    async def upload_reversed(file: bytes = File(...), form_data: str = Form(...)):
        return {"form_data": form_data, "file_len": len(file)}

    response = client.post(
        "/upload_reversed",
        data={"form_data": "hello"},
        files={"file": b"world"}
    )
    print(f"Status: {response.status_code}")
    print(f"Body: {response.json()}")
    assert response.status_code == 200
    assert response.json() == {"form_data": "hello", "file_len": 5}

if __name__ == "__main__":
    test_upload_form_then_file()
    test_upload_file_then_form()

